  it('rejects an invalid static schema at registration naming the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });

  it('returns a ToolResponse naming a missing required field and does not invoke the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registerWeatherTool(registry, async () => {
      executorCalls += 1;
      return 'sunny';
    });

    const response = await registry.execute('get_weather', {});

    expect({result: response.result, executorCalls}).toEqual({
      result: expect.stringMatching(/location.*required|required.*location/i),
